window.AUTH=window.AUTH||{};window.AUTH["23-175"]={"d":"23-175","id":"2023/23-175","n":"City of Grants Pass v. Johnson","briefs":[{"k":"petitioner","label":"Brief of petitioner City of Grants Pass","date":"2024-02-26","url":"https://www.supremecourt.gov/DocketPDF/23/23-175/301436/20240226141222543_Grants%20Pass%20v.%20Johnson_merits%20brief%20-%20TO%20FILE.pdf","side":"pet","n":77},{"k":"united-states","label":"Brief amicus curiae of United States in support of neither party","date":"2024-03-04","url":"https://www.supremecourt.gov/DocketPDF/23/23-175/302264/20240304183726571_23-175npUnitedStates.pdf","side":"us","n":24},{"k":"respondent","label":"Brief of respondents Gloria Johnson, et al.","date":"2024-03-27","url":"https://www.supremecourt.gov/DocketPDF/23/23-175/305976/20240327111905322_No%2023-175%20Grants%20Pass%20v%20Johnson%20Respondents%20Brief%20For%20Filing.pdf","side":"res","n":34},{"k":"united-states","label":"Brief amicus curiae of United States Conference of Catholic Bishops","date":"2024-04-03","url":"https://www.supremecourt.gov/DocketPDF/23/23-175/306697/20240403165912251_Grants%20Pass%20-USCCB%20Amicus%20Brief%20-%203%20April%202024.pdf","side":"us","n":9},{"k":"reply","label":"Reply of petitioner City of Grants Pass","date":"2024-04-12","url":"https://www.supremecourt.gov/DocketPDF/23/23-175/307448/20240412120319764_Grants%20Pass%20v.%20Johnson_merits%20reply%20brief.pdf","side":"pet","n":34}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/603us1r56_1bo2.pdf","tr":true,"items":[{"t":"case","label":"Badders v. United States","cite":"240 U.S. 391","y":1916,"id":"scdb/1915-109","sc":1,"sum":"Congress has power to regulate the overt.act' of putting a letter into the post office of the United States; and may. prohibit, under penalty; such an act when done in’ furtherance of a.scheme which it regards as contrary to public policy, whether it can forbid the scheme or not, and so held as to.Criminal Code, § 215.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"Browning-Ferris Industries of Vermont, Inc. v. Kelco Disposal, Inc.","cite":"492 U.S. 257","y":1989,"id":"1988/88-556","sc":1,"sum":"Respondents Joseph Kelley and Kelco Disposal, Inc., filed suit against petitioners (collectively BFI) in Federal District Court, charging BFI with antitrust violations and with interfering with Kelco's contractual relations in violation of Vermont tort law. A jury found BFI liable on both counts, and awarded Kelco, in addition to $51,146 in compensatory damages, $6 million in punitive damages on the state-law claim. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18, 19"}},{"t":"case","label":"Bucklew v. Precythe","cite":"139 S. Ct. 1112","y":2019,"id":"2018/17-8151","sc":1,"op":2,"sum":"Baze v. Rees, 553 U. S. 35, and Glossip v. Gross, 576 U. S. ___, govern all Eighth Amendment challenges alleging that a method of execution inflicts unconstitutionally cruel pain; petitioner’s as-applied challenge to Missouri’s single-drug execution protocol—that it would cause him severe pain because of his particular medical condition—fails to satisfy the Baze-Glossip test.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"3, 13, 17, 18, 19, 22, 23, 25, 27, 29","2":"39","4":"3"}},{"t":"case","label":"Chicago v. Morales","cite":"527 U.S. 41","y":1999,"id":"1998/97-1121","sc":1,"op":1,"sum":"Invalidating ordinance that failed “to distinguish between innocent conduct and conduct threatening harm”.","sumSrc":"opinion","by":{"0":"43","1":"21"}},{"t":"case","label":"Clark v. Arizona","cite":"548 U.S. 735","y":2006,"id":"2005/05-5966","sc":1,"op":5,"sum":"In a 5-to-4 decision by Justice David Souter, the Supreme Court held that Arizona could constitutionally limit the use of expert evidence about a defendant's mental state to his insanity defense.","sumSrc":"Oyez","by":{"0":"35, 44"}},{"t":"case","label":"Clark v. Community for Creative NonViolence","cite":"468 U.S. 288","y":1984,"id":"1983/82-1998","sc":1,"sum":"In a 7-to-2 decision, the Court held that the regulations did not violate the First Amendment. The Court noted that expression is subject to reasonable time, place, and manner restrictions, and that the manner of the protest was at odds with the government's interest in maintaining the condition of the parks.","sumSrc":"Oyez","by":{"0":"43","1":"23","4":"5"}},{"t":"case","label":"Coalition on Homelessness v. City and County of San Francisco","cite":"90 F.4th 975","y":2024,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/90/975/","op":5,"by":{"0":"21, 43"}},{"t":"case","label":"Coates v. Cincinnati","cite":"402 U.S. 611","y":1971,"id":"1970/117","sc":1,"sum":"Cincinnati, Ohio, ordinance making it a criminal offense for \"three or more persons to assemble... on any of the sidewalks... and there conduct themselves in a manner annoying to persons passing by...,\" which has not been narrowed by any construction of the Ohio Supreme Court, held violative on its face of the due process standard of vagueness and the constitutional right of free assembly and association. Pp. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4","4":"20"}},{"t":"case","label":"Commonwealth v. Hitchings","cite":"71 Mass. 482","y":1855,"url":"https://www.courtlistener.com/c/Mass./71/482/","by":{"0":"27"}},{"t":"case","label":"District of Columbia v. Clawans","cite":"300 U.S. 617","y":1937,"id":"scdb/1936-162","sc":1,"sum":"1. The offense of engaging, without a license, in the business of a dealer in second-band personal property, defined by the Code of the District of.Columbia, puiishable by a fine of not more than $300 or imprisonment of not more than 90 days, is to be classed as a petty offense which, consistently with Art. III, § 2, cl. 3, of the Constitution, may be tried without a jury. P. 624. 2.. In determining whether an …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"District of Columbia v. Heller","cite":"554 U.S. 570","y":2008,"id":"2007/07-290","sc":1,"sum":"The Court found a District of Columbia law strictly regulating gun ownership to be unconstitutional.","sumSrc":"Oyez","by":{"0":"16"}},{"t":"case","label":"Edwards v. Vannoy","cite":"593 U.S. 255","y":2021,"id":"2020/19-5807","sc":1,"sum":"The jury-unanimity rule announced in Ramos v. Louisiana, 590 U. S. ___, does not apply retroactively on federal collateral review.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"40"}},{"t":"case","label":"Estelle v. Gamble","cite":"429 U.S. 97","y":1976,"id":"1976/75-929","sc":1,"sum":"The Court held that the prison’s treatment of Gamble did not constitute cruel and unusual punishment under the Eighth Amendment.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Ewing v. California","cite":"538 U.S. 11","y":2003,"id":"2002/01-6978","sc":1,"sum":"In a 5-4 plurality decision authored by Justice Sandra Day O'Connor, the Court, relying heavily on its decision in Rummel v. Estelle (1980), concluded that Ewing's long history of legal offenses justified his conviction. In Rummel , the Court had ruled that a sentence of life with the possibility of parole was valid for three convictions of fraud, check forgery, and theft.","sumSrc":"Oyez","by":{"0":"23, 44"}},{"t":"case","label":"Louisiana ex rel. Francis v. Resweber","cite":"329 U.S. 459","y":1947,"id":"1940-1955/329us459","sc":1,"sum":"No and no. The equipment failure does not bring due process into play. This was not the wanton infliction of unnecessary pain in the execution of the death sentence. And the cruelty of the Eighth Amendment refers to cruelty in method, not that cruelty which is part of the actual suffering accompanying a lawful sentence of death.","sumSrc":"Oyez","by":{"0":"38, 39"}},{"t":"case","label":"Gamble v. United States","cite":"139 S. Ct. 1960","y":2019,"id":"2018/17-646","sc":1,"sum":"The dual sovereignty doctrine—under which two offenses are not the “same offence” for double jeopardy purposes if prosecuted by separate sovereigns—is upheld.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"16"}},{"t":"case","label":"Georgia v. Public.Resource.Org, Inc.","cite":"140 S. Ct. 1498","y":2020,"id":"2019/18-1150","sc":1,"sum":"The Court held that the government edict doctrine extends to—and thus renders uncopyrightable—the annotations in the Official Code of Georgia Annotated.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Glossip v. Gross","cite":"576 U.S. 863","y":2015,"id":"2014/14-7955","sc":1,"sum":"The Court held that the use of midazolam as the initial drug in a state’s execution protocol does not violate the Eighth Amendment’s prohibition against cruel and unusual punishment.","sumSrc":"Oyez","by":{"0":"22, 23"}},{"t":"case","label":"Graham v. Florida","cite":"560 U.S. 48","y":2010,"id":"2009/08-7412","sc":1,"sum":"The Court found that a non-homicidal conviction leading to a life sentence without parole for a juvenile violates the Eighth Amendment.","sumSrc":"Oyez","by":{"0":"23, 28","2":"27, 28, 29, 31, 32, 44","3":"11","4":"10, 20, 21"}},{"t":"case","label":"Hague v. Committee for Industrial Organization","cite":"307 U.S. 496","y":1939,"id":"1900-1940/307us496","sc":1,"sum":"The Court held that enforcement of a Jersey City ordinance violated the CIO's right to assembly under the First Amendment as applied to the states by the Fourteenth Amendment.","sumSrc":"Oyez","by":{"0":"4"}},{"t":"case","label":"Harmelin v. Michigan","cite":"501 U.S. 957","y":1991,"id":"1990/89-7272","sc":1,"sum":"The Court, in a 5-to-4 decision, held that since the Eighth Amendment does not contain a proportionality guarantee, the determination of whether a punishment is \"cruel and unusual\" is not made with reference to the particular offense. Moreover, the Cruel and Unusual Punishment Clause protects against unusual methods of punishment, not necessarily cruel ones.","sumSrc":"Oyez","by":{"0":"18, 20, 22","2":"27","4":"11"}},{"t":"case","label":"Howard v. Fleming","cite":"191 U.S. 126","y":1903,"id":"scdb/1903-036","sc":1,"sum":"The decision of the highest court of a State that conspiracy to defraud is a common law offense and as such/cognizable in the courts of that State, although there be no statute defining or punishing such a crime, is not a Federal question, nor re viewable by this court. Nor can this court inquire whether the indictment sufficiently charged the offense.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Hutcherson v. United States","cite":"345 F.2d 964","y":1965,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/345/964/","by":{"0":"44"}},{"t":"case","label":"Ingraham v. Wright","cite":"430 U.S. 651","y":1977,"id":"1976/75-6527","sc":1,"op":2,"sum":"The Court held that the Eighth Amendment does not prevent corporal punishment in public schools. While acknowledging the general abandonment of corporal punishment as a means of punishing criminals, Justice Powell looked to the common law history of similar punishment in schools and discerned no trend towards its elimination.","sumSrc":"Oyez","by":{"0":"12, 20, 22, 35, 40","1":"14, 17, 19","2":"27","4":"9, 17"}},{"t":"case","label":"Inouye v. Kemna","cite":"504 F.3d 705","y":2007,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/504/705/","by":{"0":"46"}},{"t":"case","label":"Janus v. State, County and Municipal Employees","cite":"138 S. Ct. 2448","y":2018,"id":"2017/16-1466","sc":1,"sum":"The Court decided the State of Illinois’ extraction of agency fees from nonconsenting public-sector employees violates the First Amendment; Abood v. Detroit Bd. of Ed., 431 U.S. 209 (1977), which held otherwise, was overruled.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Jones v. United States","cite":"463 U.S. 354","y":1983,"id":"1982/81-5195","sc":1,"op":1,"sum":"When a criminal defendant establishes by a preponderance of the evidence that he is not guilty of a crime by reason of insanity, the Constitution permits the Government, on the basis of the insanity judgment, to confine him to a mental institution until such time as he has regained his sanity or is no longer a danger to himself or society.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"Joyce v. City and County of San Francisco","cite":"846 F. Supp. 843","y":1994,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp./846/843/","by":{"0":"45"}},{"t":"case","label":"Kahler v. Kansas","cite":"140 S. Ct. 1021","y":2020,"id":"2019/18-6135","sc":1,"op":6,"ar":4,"sum":"The Court held that it does not violate the Eighth and Fourteenth Amendments for a state to abolish the insanity defense.","sumSrc":"Oyez","by":{"0":"5, 14, 35, 42, 44","1":"25","2":"24","4":"8, 15, 24"}},{"t":"case","label":"Kennedy v. Louisiana","cite":"554 U.S. 407","y":2008,"id":"2007/07-343","sc":1,"sum":"The Court held that the Eighth Amendment prevented states from imposing the death penalty for the rape of a child, in which death was not intended nor resulted from the rape.","sumSrc":"Oyez","by":{"0":"23","2":"39","4":"12"}},{"t":"case","label":"Kimble v. Marvel Entertainment, LLC","cite":"576 U.S. 446","y":2015,"id":"2014/13-720","sc":1,"sum":"The Court determined that its earlier decision in Brulotte v. Thys Co. , which held that a patentee cannot continue to receive royalties after the expiration of the patent, should be upheld.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Leland v. Oregon","cite":"343 U.S. 790","y":1952,"id":"scdb/1951-094","sc":1,"op":1,"sum":"These statutes did not deprive appellant of life and liberty without due process of law in violation of the Fourteenth Amendment of the Federal Constitution.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44"}},{"t":"case","label":"Lemon v. Kurtzman","cite":"403 U.S. 602","y":1971,"id":"1970/89","sc":1,"sum":"The Court found that Pennsylvania and Rhode Island statutes granting salary supplements to teachers at \"church-related educational institutions\" was unconstitutional for violating the Establishment Clause of the First Amendment. The case established the Lemon Test for determining if the government is becoming too involved in religious activities.","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"Mahoney v. Sacramento","cite":"2020 WL 616302","y":2020,"court":"E.D. Cal. Feb. 10","op":1,"by":{"0":"48"}},{"t":"case","label":"Manning v. Caldwell","cite":"930 F.3d 264","y":2019,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/930/264/","op":1,"by":{"0":"35","2":"22"}},{"t":"case","label":"Marks v. United States","cite":"430 U.S. 188","y":1977,"id":"1976/75-708","sc":1,"sum":"The Due Process Clause of the Fifth Amendment precludes retroactive application to petitioners of the Miller standards, to the extent that those standards may impose criminal liability for conduct not punishable under the standards announced in Memoirs v. Massachusetts, 383 U. S. 413. Bouie v. City of Columbia, 378 U. S. 347. Specifically, petitioners are entitled to jury instructions requiring the jury to acquit …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14, 35, 36","1":"25"}},{"t":"case","label":"Marshall v. United States","cite":"414 U.S. 417","y":1974,"id":"1973/72-5881","sc":1,"op":22,"ar":1,"sum":"Title II of NARA does not deny due process or equal protection by excluding from rehabilitative commitment, in lieu of penal incarceration, addicts with two or more prior felony convictions, since Congress could rationally assume that an addict with a multiple-felony record is likely to benefit less from rehabilitative treatment, present a possible impediment to the successful treatment of others, and be a greater …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"Martin v. Boise","cite":"920 F.3d 584","y":2019,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/920/584/","op":11,"by":{"0":"7, 8, 9, 13, 15","1":"10, 24, 28, 29","2":"8, 9","4":"2, 9"}},{"t":"case","label":"20, 21, 29, 30, 35, 36, 42, 46, 48 Medina v. California","cite":"505 U.S. 437","y":1992,"id":"1991/90-8370","sc":1,"sum":"Before petitioner Medina's trial for, inter alia, first-degree murder, the California court granted his motion for a competency hearing pursuant to a state law that forbids a mentally incompetent person to be tried or punished, establishes a presumption of competence, and placed on petitioner the burden of proving incompetence by a preponderance of the evidence. The jury empaneled for the competency hearing found …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42"}},{"t":"case","label":"Miller v. Alabama","cite":"567 U.S. 460","y":2012,"id":"2011/10-9646","sc":1,"op":2,"sum":"The Court found it to be a violation of the Eighth Amendment to impose a sentence of life imprisonment without the possibility of parole on juvenile offenders.","sumSrc":"Oyez","by":{"0":"23","2":"27","4":"9"}},{"t":"case","label":"Montana v. Egelhoff","cite":"518 U.S. 37","y":1996,"id":"1995/95-566","sc":1,"op":2,"sum":"The Court could not reach a majority on the reasons for its decision. Justice Antonin Scalia, who announced the judgment of the Court, declared that defendants do not have an absolute constitutional right to present all relevant evidence in their defense.","sumSrc":"Oyez","by":{"0":"35, 42"}},{"t":"case","label":"Nichols v. United States","cite":"511 U.S. 738","y":1994,"id":"1993/92-8556","sc":1,"sum":"After petitioner Nichols pleaded guilty to federal felony drug charges, he was assessed criminal history points under the United States Sentencing Guidelines, including one point for a state misdemeanor conviction for driving while under the influence (DUI), for which he was fined but not incarcerated. That point increased the maximum sentence of imprisonment from 210 to 235 months. Petitioner objected to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"Papachristou v. Jacksonville","cite":"405 U.S. 156","y":1972,"id":"1971/70-5030","sc":1,"op":1,"ar":1,"sum":"Concluding that vagrancy law employing “ `archaic language' ” in its defnition was “void for vagueness”.","sumSrc":"opinion","by":{"0":"43"}},{"t":"case","label":"Parents Involved in Community Schools v. Seattle School Dist. No. 1","cite":"551 U.S. 701","y":2007,"id":"2006/05-915","sc":1,"sum":"By a 5-4 vote, the Court applied a \"strict scrutiny\" framework and found Jefferson County's enrollment plan unconstitutional under the Equal Protection Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Patterson v. New York","cite":"432 U.S. 197","y":1977,"id":"1976/75-1861","sc":1,"sum":"New York law requiring that the defendant in a prosecution for seconddegree murder prove by a preponderance of the evidence the affirmative defense of extreme emotional disturbance in order to reduce the crime to manslaughter held not to violate the Due Process Clause of the Fourteenth Amendment. Mullaney v. Wilbur, 421 U. S. 684, distinguished.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42"}},{"t":"case","label":"Powell v. Texas","cite":"392 U.S. 514","y":1968,"id":"1967/405","sc":1,"op":32,"ar":9,"sum":"The plurality found that the record did not prove that alcoholics were totally unable to control their alcohol consumption. The law prohibiting public intoxication did not punish Powell for his alcoholism, but for his being drunk in a public location. Chief Justice Earl Warren, Justice Hugo L. Black, and Justice John M. Harlan joined in the plurality.","sumSrc":"Oyez","by":{"0":"4, 6, 13, 30, 32, 33, 34, 35, 36, 37, 39, 40, 44, 48","1":"9, 14, 18, 19, 24, 25","2":"22","3":"16, 17","4":"1, 4, 5, 8, 11, 20, 21, 24"}},{"t":"case","label":"Ramos v. Louisiana","cite":"140 S. Ct. 1390","y":2020,"id":"2019/18-5924","sc":1,"sum":"The Court held that the Fourteenth Amendment fully incorporates the Sixth Amendment’s guarantee of a unanimous verdict against the states.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Robinson v. California","cite":"370 U.S. 660","y":1962,"id":"1961/554","sc":1,"op":11,"sum":"The Court held that laws criminalizing the \"illness\" of narcotic addiction inflicted cruel and unusual punishment in violation of the Eighth and Fourteenth Amendments.","sumSrc":"Oyez","by":{"0":"4, 13, 15, 29, 30, 31, 32, 37, 38, 39, 45","1":"9, 16-18, 20","2":"1, 12, 13, 18, 19, 20, 28, 29, 30","3":"15, 16, 17","4":"2, 4, 5, 6"}},{"t":"case","label":"Roper v. Simmons","cite":"543 U.S. 551","y":2005,"id":"2004/03-633","sc":1,"op":2,"sum":"The Court held that executing minors under the death penalty is unconstitutional.","sumSrc":"Oyez","by":{"0":"23","2":"39, 40","3":"10","4":"12"}},{"t":"case","label":"Rummel v. Estelle","cite":"445 U.S. 263","y":1980,"id":"1979/78-6386","sc":1,"sum":"In a 5-to-4 decision, the Court held that the life sentence imposed by Texas law did not constitute cruel and unusual punishment under the Eighth and Fourteenth Amendments.","sumSrc":"Oyez","by":{"0":"23","4":"10"}},{"t":"case","label":"Solem v. Helm","cite":"463 U.S. 277","y":1983,"id":"1982/82-492","sc":1,"sum":"Since all of Helm's prior offenses, including his current check-writing conviction, had been \"relatively minor\" and were not crimes against people, Justice Powell held that Helm had \"received the penultimate sentence (South Dakota did not have the death penalty) for relatively minor criminal conduct.\" Powell concluded that Helm was treated more harshly than the state's most violent criminals.","sumSrc":"Oyez","by":{"0":"28","2":"27","3":"11"}},{"t":"case","label":"State v. Barrett","cite":"460 P.3d 93","y":2020,"court":"Or. App.","url":"https://www.courtlistener.com/c/P.3d/460/93/","op":1,"by":{"0":"41"}},{"t":"case","label":"State v. Little","cite":"261 N.W.2d 847","y":1978,"court":"Neb.","url":"https://www.courtlistener.com/c/N.W.2d/261/847/","by":{"0":"49"}},{"t":"case","label":"Timbs v. Indiana","cite":"139 S. Ct. 682","y":2019,"id":"2018/17-1091","sc":1,"op":2,"sum":"The Eighth Amendment’s Excessive Fines Clause is an incorporated protection applicable to the States under the Fourteenth Amendment’s Due Process Clause.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"25","2":"37"}},{"t":"case","label":"Tobe v. Santa Ana","cite":"892 P.2d 1145","y":1995,"court":"Cal.","url":"https://www.courtlistener.com/c/P.2d/892/1145/","by":{"0":"45"}},{"t":"case","label":"Town of Greece v. Galloway","cite":"572 U.S. 565","y":2014,"id":"2013/12-696","sc":1,"sum":"The Court ruled that the invocation of prayer at a legislative session does not violate the Establishment Clause of the First Amendment.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Trop v. Dulles","cite":"356 U.S. 86","y":1958,"id":"1956/70","sc":1,"op":3,"ar":2,"sum":"Concluding that a law that banishes people threatens “the total destruction of the individual's status in organized society”.","sumSrc":"opinion","by":{"0":"27"}},{"t":"case","label":"United States v. Balsys","cite":"524 U.S. 666","y":1998,"id":"1997/97-873","sc":1,"sum":"In a 7-to-2 decision, the Court held that although resident aliens are entitled to the same Fifth Amendment protections as citizen \"persons\" the risk of their deportation is not sufficient to sustain a self-incrimination privilege intended to apply only to the United States government.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"United States v. Black","cite":"116 F.3d 198","y":1997,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/116/198/","by":{"0":"49"}},{"t":"case","label":"United States v. Moore","cite":"486 F.2d 1139","y":1973,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/486/1139/","by":{"0":"48"}},{"t":"case","label":"United States v. Palomar-Santiago","cite":"593 U.S. 321","y":2021,"id":"2020/20-437","sc":1,"sum":"Each of 8 U. S. C. §1326(d)’s statutory requirements for bringing a collateral attack on a prior deportation order is mandatory.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"18"}},{"t":"case","label":"Washington v. Glucksberg","cite":"521 U.S. 702","y":1997,"id":"1996/96-110","sc":1,"op":6,"sum":"The Court decided that a law banning physician-assisted suicide does not violate the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Weems v. United States","cite":"217 U.S. 349","y":1910,"id":"scdb/1909-139","sc":1,"ar":2,"sum":"A paramount governmental authority may make use of subordinate governmental instruments, without the creation of a distinct legal entity as is the case of the United States and the United States Government of the Philippine Islands.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"21, 24, 27, 28","2":"27, 39, 46","3":"11"}},{"t":"case","label":"Whitten v. State","cite":"47 Ga. 297","y":1872,"url":"https://www.courtlistener.com/c/Ga./47/297/","by":{"0":"27"}},{"t":"case","label":"Wilkerson v. Utah","cite":"99 U.S. 130","y":1879,"id":"scdb/1878-134","sc":1,"ar":1,"by":{"0":"17, 23, 38"}},{"t":"case","label":"Wilson v. Seiter","cite":"501 U.S. 294","y":1991,"id":"1990/89-7376","sc":1,"sum":"No and Yes. Justice Antonin Scalia delivered the opinion for a unanimous court.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"const","label":"Article I, Section 9, Clause 3","clauses":[["attainder-ex-post-facto","Bills of Attainder and Ex Post Facto Laws"]],"text":"No Bill of Attainder or ex post facto Law shall be passed.","by":{"0":"19"}},{"t":"const","label":"Article I, Section 10, Clause 1","clauses":[["contract-clause","Contract Clause"]],"text":"No State shall enter into any Treaty, Alliance, or Confederation; grant Letters of Marque and Reprisal; coin Money; emit Bills of Credit; make any Thing but gold and silver Coin a Tender in Payment of Debts; pass any Bill of Attainder, ex post facto Law, or Law impairing the Obligation of Contracts, or grant any Title of Nobility.","by":{"0":"19"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"0":"19"}},{"t":"const","label":"Amendment VIII","clauses":[["eighth-amendment","Eighth Amendment"]],"text":"Excessive bail shall not be required, nor excessive fines imposed, nor cruel and unusual punishments inflicted.","by":{"0":"12, 16","1":"9, 13, 14, 16-19, 21, 22, 24, 27, 32","4":"1"}},{"t":"usc","label":"18 U.S.C. § 1863","url":"https://www.law.cornell.edu/uscode/text/18/1863","by":{"0":"43"}},{"t":"usc","label":"18 U.S.C. § 3571","url":"https://www.law.cornell.edu/uscode/text/18/3571","by":{"0":"28"}},{"t":"usc","label":"18 U.S.C. § 3581","url":"https://www.law.cornell.edu/uscode/text/18/3581","by":{"0":"28"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"2"}},{"t":"usc","label":"42 U.S.C. § 11434a","url":"https://www.law.cornell.edu/uscode/text/42/11434a","stext":{"head":"§11434a. Definitions","paras":[[0,"For purposes of this part:"],[1,"(1) The terms \"enroll\" and \"enrollment\" include attending classes and participating fully in school activities."],[1,"(2) The term \"homeless children and youths\"—"],[2,"(A) means individuals who lack a fixed, regular, and adequate nighttime residence (within the meaning of section 11302(a)(1) of this title); and"],[2,"(B) includes—"],[3,"(i) children and youths who are sharing the housing of other persons due to loss of housing, economic hardship, or a similar reason; are living in motels, hotels, trailer parks, or camping grounds due to the lack of alternative adequate accommodations; are living in emergency or transitional shelters; or are abandoned in hospitals;"],[3,"(ii) children and youths who have a primary nighttime residence that is a public or private place not designed for or ordinarily used as a regular sleeping accommodation for human beings (within the meaning of section 11302(a)(2)(C) 1 of this title);"],[3,"(iii) children and youths who are living in cars, parks, public spaces, abandoned buildings, substandard housing, bus or train stations, or similar settings; and"],[3,"(iv) migratory children (as such term is defined in section 6399 of title 20) who qualify as homeless for the purposes of this part because the children are living in circumstances described in clauses (i) through (iii)."],[1,"(3) The terms \"local educational agency\" and \"State educational agency\" have the meanings given such terms in section 7801 of title 20."],[1,"(4) The term \"Secretary\" means the Secretary of Education."],[1,"(5) The term \"State\" means each of the 50 States, the District of Columbia, and the Commonwealth of Puerto Rico."],[1,"(6) The term \"unaccompanied youth\" includes a homeless child or youth not in the physical custody of a parent or guardian."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/11434a?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§11434a. Definitions","tname":"The Public Health and Welfare","by":{"0":"46"}},{"t":"reg","label":"24 C.F.R. § 578.7","url":"https://www.ecfr.gov/current/title-24/section-578.7","by":{"0":"46"}},{"t":"reg","label":"24 C.F.R. § 582.5","url":"https://www.ecfr.gov/current/title-24/section-582.5","by":{"0":"46","4":"6"}},{"t":"case","label":"(III) Cases—Continued: Edwards v. California","cite":"314 U.S. 160","y":1941,"id":"1940-1955/314us160","sc":1,"sum":"The Commerce Clause forbids a state to exclude indigents. California's interest in the health of its citizens and the sufficiency of its welfare funds do not justify the burden on interstate commerce occasioned by the law.","sumSrc":"Oyez","by":{"1":"27","2":"23, 24","4":"14"}},{"t":"case","label":"Johnson v. City of Dallas","cite":"860 F. Supp. 344","y":1994,"court":"N.D. Tex.","url":"https://www.courtlistener.com/c/F.%20Supp./860/344/","by":{"1":"19, 20"}},{"t":"case","label":"Jones v. City of Los Angeles","cite":"444 F.3d 1118","y":2006,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/444/1118/","op":14,"by":{"1":"19","4":"22"}},{"t":"case","label":"Pottinger v. City of Miami","cite":"810 F. Supp. 1551","y":1992,"court":"S.D. Fla.","url":"https://www.courtlistener.com/c/F.%20Supp./810/1551/","op":1,"sum":"Concluding that “enforcement of laws that prevent homeless individuals who have no place to go from sleeping” might also unconstitutionally “burde[n] their right to travel”.","sumSrc":"opinion","by":{"1":"19, 20"}},{"t":"case","label":"Saenz v. Roe","cite":"526 U.S. 489","y":1999,"id":"1998/98-97","sc":1,"op":1,"ar":2,"sum":"In a 7-to-2 decision, the Court held that the Fourteenth Amendment protects the right to travel in three ways by: allowing citizens to move freely between states, securing the right to be treated equally in all states when visiting, and securing the rights of new citizens to be treated like long-time citizens of a state.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"United States v. Wheeler","cite":"254 U.S. 281","y":1920,"id":"scdb/1920-008","sc":1,"sum":"1. 'In all the States, from the beginning down to the' establishment of the Articles of Confederation, the citizens possessed the right, inherent in citizens of all free governments, peacefully to dwell within the limits of their respective States, to move at will from place to place therein, and to have free ingress thereto and egress therefrom. A consequent authority resided in the States to forbid and punish …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"Wal-Mart Stores, Inc. v. Dukes","cite":"564 U.S. 338","y":2011,"id":"2010/10-277","sc":1,"sum":"The Court held that the small group who initiated a lawsuit could not represent all of Wal-Mart's female employees, and therefore could not bring a class action lawsuit against Wal-Mart.","sumSrc":"Oyez","by":{"1":"12, 31","2":"49"}},{"t":"const","label":"Amendment XIV","clauses":[["due-process-14","Due Process Clause (Fourteenth Amendment)"]],"by":{"1":"22"}},{"t":"usc","label":"34 U.S.C. § 12601","url":"https://www.law.cornell.edu/uscode/text/34/12601","by":{"1":"1"}},{"t":"usc","label":"40 U.S.C. § 1315","url":"https://www.law.cornell.edu/uscode/text/40/1315","subs":["(a)"],"by":{"1":"8"}},{"t":"usc","label":"42 U.S.C. § 11312","url":"https://www.law.cornell.edu/uscode/text/42/11312","by":{"1":"3"}},{"t":"usc","label":"42 U.S.C. § 11313","url":"https://www.law.cornell.edu/uscode/text/42/11313","subs":["(a)(12)"],"stext":{"head":"§11313. Functions","paras":[[0,"(a) Duties"],[0,"The Council shall—"],[1,"(1) not later than 12 months after May 20, 2009, develop, make available for public comment, and submit to the President and to Congress a National Strategic Plan to End Homelessness, and shall update such plan annually;"],[1,"(2) review all Federal activities and programs to assist homeless individuals;"],[1,"(3) take such actions as may be necessary to reduce duplication among programs and activities by Federal agencies to assist homeless individuals;"],[1,"(4) monitor, evaluate, and recommend improvements in programs and activities to assist homeless individuals conducted by Federal agencies, State and local governments, and private voluntary organizations;"],[1,"(5) provide professional and technical assistance (by not less than 5, but in no case more than 10, regional coordinators employed by the Council, each having responsibility for interaction and coordination of the activities of the Council within the 10 standard Federal regions) to States, local governments, and other public and private nonprofit organizations, in order to enable such governments and organizations to—"],[2,"(A) interpret regulations and assist in the application process for Federal assistance, including grants;"],[2,"(B) provide assistance on the ways in which Federal programs, other than those authorized under this chapter, may best be coordinated to complement the objectives of this chapter;"],[2,"(C) develop recommendations and program ideas based on regional specific issues in serving the homeless population; and"],[2,"(D) establish a schedule for biennial regional workshops to be held by the Council in each of the 10 standard Federal regions to further carry out and provide the assistance described in subparagraphs (A), (B), and (C) and other appropriate assistance as necessary, of which—"],[3,"(i) not less than 5 such workshops shall be held by September 30, 1989; and"],[3,"(ii) at least 1 such workshop shall be held in each of the 10 Federal regions every 2 years, beginning on September 30, 1988;"],[1,"(6) encourage the creation of State Interagency Councils on Homelessness and the formulation of jurisdictional 10-year plans to end homelessness at State, city, and county levels;"],[1,"(7) annually obtain from Federal agencies their identification of consumer-oriented entitlement and other resources for which persons experiencing homelessness may be eligible and the agencies' identification of improvements to ensure access; develop mechanisms to ensure access by persons experiencing homelessness to all Federal, State, and local programs for which the persons are eligible, and to verify collaboration among entities within a community that receive Federal funding under programs targeted for persons experiencing homelessness, and other programs for which persons experiencing homelessness are eligible, including mainstream programs identified by the Government Accountability Office in the reports entitled \"Homelessness: Coordination and Evaluation of Programs Are Essential\", issued February 26, 1999, and \"Homelessness: Barriers to Using Mainstream Programs\", issued July 6, 2000;"],[1,"(8) conduct research and evaluation related to its functions as defined in this section;"],[1,"(9) 1 develop joint Federal agency and other initiatives to fulfill the goals of the agency;"],[1,"(9) 1 collect and disseminate information relating to homeless individuals;"],[1,"(10) prepare the annual reports required in subsection (c)(2);"],[1,"(11) prepare and distribute to States (including State contact persons), local governments, and other public and private nonprofit organizations, a bimonthly bulletin that describes the Federal resources available to them to assist the homeless, including current information regarding application deadlines and appropriate persons to contact in each Federal agency providing the resources;"],[1,"(12) develop constructive alternatives to criminalizing homelessness and laws and policies that prohibit sleeping, feeding, sitting, resting, or lying in public spaces when there are no suitable alternatives, result in the destruction of a homeless person's property without due process, or are selectively enforced against homeless persons; and"],[1,"(13) not later than the expiration of the 6-month period beginning upon completion of the study requested in a letter to the Acting Comptroller General from the Chair and Ranking Member of the House Financial Services Committee and several other members regarding various definitions of homelessness in Federal statutes, convene a meeting of representatives of all Federal agencies and committees of the House of Representatives and the Senate having jurisdiction over any Federal program to assist homeless individuals or families, local and State governments, academic researchers who specialize in homelessness, nonprofit housing and service providers that receive funding under any Federal program to assist homeless individuals or families, organizations advocating on behalf of such nonprofit providers and homeless persons receiving housing or services under any such Federal program, and homeless persons receiving housing or services under any such Federal program, at which meeting such representatives shall discuss all issues relevant to whether the definitions of \"homeless\" under paragraphs (1) through (4) of section 11302(a) of this title, as amended by section 1003 of the Homeless Emergency Assistance and Rapid Transition to Housing Act of 2009, should be modified by the Congress, including whether there is a compelling need for a uniform definition of homelessness under Federal law, the extent to which the differences in such definitions create barriers for individuals to accessing services and to collaboration between agencies, and the relative availability, and barriers to access by persons defined as homeless, of mainstream programs identified by the Government Accountability Office in the two reports identified in paragraph (7) of this subsection; and shall submit transcripts of such meeting, and any majority and dissenting recommendations from such meetings, to each committee of the House of Representatives and the Senate having jurisdiction over any Federal program to assist homeless individuals or families not later than the expiration of the 60-day period beginning upon conclusion of such meeting."],[0,"(b) Authority"],[0,"In carrying out subsection (a), the Council may—"],[1,"(1) arrange national, regional, State, and local conferences for the purpose of developing and coordinating effective programs and activities to assist homeless individuals and pay for expenses of attendance at meetings which are concerned with the functions or activities for which the appropriation is made; 2"],[1,"(2) publish a newsletter concerning Federal, State, and local programs that are effectively meeting the needs of homeless individuals."],[0,"(c) Reports"],[0,"(1) Within 90 days after July 22, 1987, and annually thereafter, the head of each Federal agency that is a member of the Council shall prepare and transmit to the Congress and the Council a report that describes—"],[1,"(A) each program to assist homeless individuals administered by such agency and the number of homeless individuals served by such program;"],[1,"(B) impediments, including any statutory and regulatory restrictions, to the use by homeless individuals of each such program and to obtaining services or benefits under each such program; and"],[1,"(C) efforts made by such agency to increase the opportunities for homeless individuals to obtain shelter, food, and supportive services."],[0,"(2) The Council shall prepare and transmit to the President and the Congress an annual report that—"],[1,"(A) assesses the nature and extent of the problems relating to homelessness and the needs of homeless individuals;"],[1,"(B) provides a comprehensive and detailed description of the activities and accomplishments of the Federal Government in resolving the problems and meeting the needs assessed pursuant to subparagraph (A);"],[1,"(C) describes the accomplishments and activities of the Council, in working with Federal, State, and local agencies and public and private organizations in order to provide assistance to homeless individuals;"],[1,"(D) assesses the level of Federal assistance necessary to adequately resolve the problems and meet the needs assessed pursuant to subparagraph (A); and"],[1,"(E) specifies any recommendations of the Council for appropriate and necessary legislative and administrative actions to resolve such problems and meet such needs."],[0,"(d) Notification of other Federal agencies"],[0,"If, in monitoring and evaluating programs and activities to assist homeless individuals conducted by other Federal agencies, the Council determines that any significant problem, abuse, or deficiency exists in the administration of the program or activity of any Federal agency, the Council shall submit a notice of the determination of the Council to the Inspector General of the Federal agency (or the head of the Federal agency, in the case of a Federal agency that has no Inspector General)."],[0,"(e) Program timetables"],[0,"Not later than 90 days after November 7, 1988, the head of each Federal agency that is a member of the Council and responsible for administering a program under this chapter shall provide to the Council a timetable regarding program funding availability and application deadlines. The Council shall furnish such information to each State (including the State contact person)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/11313?type=usc&year=mostrecent&link-type=html"},"head":"§11313. Functions","tname":"The Public Health and Welfare","by":{"1":"1, 3","2":"43"}},{"t":"reg","label":"36 C.F.R. § 7.96","url":"https://www.ecfr.gov/current/title-36/section-7.96","subs":["(i)"],"by":{"1":"6","4":"5"}},{"t":"reg","label":"47 Fed. Reg. 24,299","url":"https://www.govinfo.gov/link/fr/47/24299","by":{"1":"6"}},{"t":"case","label":"Atkins v. Virginia","cite":"536 U.S. 304","y":2002,"id":"2001/00-8452","sc":1,"sum":"The Court found that sentencing a mentally disabled person to death is a violation of the Eighth Amendment's Cruel and Unusual Punishment Clause.","sumSrc":"Oyez","by":{"2":"27, 39, 40","3":"10"}},{"t":"case","label":"Bartlett v. Strickland","cite":"556 U.S. 1","y":2009,"id":"2008/07-689","sc":1,"ar":1,"sum":"The Court found that the Voting Rights Act of 1965 did not require redistricting in a county lacking a numerical majority of a racial minority of citizens.","sumSrc":"Oyez","by":{"2":"25"}},{"t":"case","label":"Coker v. Georgia","cite":"433 U.S. 584","y":1977,"id":"1976/75-5444","sc":1,"sum":"The Court ruled that use of the capital punishment as a penalty for rape was a form of cruel and unusual punishment forbidden by the Eighth Amendment.","sumSrc":"Oyez","by":{"2":"12, 27, 31"}},{"t":"case","label":"Corfield v. Coryell","cite":"6 F. Cas. 546","y":1823,"court":"C.C.E.D. Pa.","url":"https://www.courtlistener.com/c/F.%20Cas./6/546/","by":{"2":"32"}},{"t":"case","label":"Enmund v. Florida","cite":"458 U.S. 782","y":1982,"id":"1981/81-5321","sc":1,"sum":"The Supreme Court held that imposing the death penalty on someone who aided and abetted but did not himself kill, attempt to kill, or intend to kill, violated the Eight and Fourteenth Amendments. It is unlikely that the death penalty could deter someone who did not intend to kill or attempt to kill, and putting someone to death for two killings they did not commit is disproportionate retribution.","sumSrc":"Oyez","by":{"2":"27, 28, 29, 41","4":"10"}},{"t":"case","label":"Felton v. United States","cite":"96 U.S. 699","y":1877,"id":"scdb/1877-242","sc":1,"sum":". The sixteenth section of. the act of July 20, 1868, imposing taxes on distilled spirits (15 Stat. 131), provides, among other things, that the owner, -agent, or -superintendent of any distillery'shall erect in'a room or building, to be provided-and used solely for that purpose, two or more, receiving cisterns; each to be at least of sufficient capacity to hold all the spirits distilled during twenty-four hours, …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"24"}},{"t":"case","label":"Graham v. Connor","cite":"490 U.S. 386","y":1989,"id":"1988/87-6571","sc":1,"sum":"In a unanimous ruling written by Justice William Rehnquist, the Court held that claims of excessive force used by government officials are properly analyzed under the Fourth Amendment’s “objective reasonableness” standard. The Court vacated the directed verdict and remanded the case to the district court to be decided by that standard.","sumSrc":"Oyez","by":{"2":"24"}},{"t":"case","label":"Gregg v. Georgia","cite":"428 U.S. 153","y":1976,"id":"1975/74-6257","sc":1,"op":1,"sum":"The Court ruled that the death penalty was not \"cruel and unusual\" punishment in violation of the Eighth and Fourteenth Amendments.","sumSrc":"Oyez","by":{"2":"27, 33","3":"10, 11"}},{"t":"case","label":"Haaland v. Brackeen","cite":"599 U.S. 255","y":2023,"id":"2022/21-376","sc":1,"sum":"In child custody proceedings governed by the Indian Child Welfare Act, the Court affirms the Fifth Circuit’s conclusion that ICWA is consistent with Congress’s Article I authority, rejects petitioners’ anticommandeering challenges under the Tenth Amendment, and finds the parties lack standing to litigate their other challenges to ICWA’s placement preferences.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"15, 45"}},{"t":"case","label":"Hicks v. State","cite":"76 Ga. 326","y":1886,"url":"https://www.courtlistener.com/c/Ga./76/326/","by":{"2":"38"}},{"t":"case","label":"McDonald v. City of Chicago","cite":"561 U.S. 742","y":2010,"id":"2009/08-1521","sc":1,"sum":"The Court held that the Fourteenth Amendment makes the Second Amendment's right to bear arms for the purpose of self-defense applicable in the states.","sumSrc":"Oyez","by":{"2":"23"}},{"t":"case","label":"Montgomery v. Louisiana","cite":"577 U.S. 190","y":2016,"id":"2015/14-280","sc":1,"sum":"The Court held that the Supreme Court’s decision in Miller v. Alabama, which prohibits sentencing schemes that impose a punishment of mandatory life without parole for juvenile offenders convicted of homicide, applied retroactively.","sumSrc":"Oyez","by":{"2":"28","4":"10"}},{"t":"case","label":"Taylor v. Georgia","cite":"315 U.S. 25","y":1942,"id":"scdb/1941-161","sc":1,"sum":"Striking down law that imposed criminal punishment for failure to fulfill labor contract, as a form of unconstitutional “peonage”.","sumSrc":"brief:2","by":{"2":"37"}},{"t":"case","label":"Thompson v. Bunton","cite":"22 S.W. 863","y":1893,"court":"Mo.","url":"https://www.courtlistener.com/c/S.W./22/863/","op":1,"sum":"Striking down law allowing vagrants’ labor to be auctioned off to the highest bidder.","sumSrc":"brief:2","by":{"2":"37"}},{"t":"rule","label":"Fed. R. Civ. P. 23","url":"https://www.law.cornell.edu/rules/frcp/rule_23","subs":["(a)","(b)(2)"],"by":{"2":"49, 15, 48, 49"}},{"t":"usc","label":"42 U.S.C. § 11302","url":"https://www.law.cornell.edu/uscode/text/42/11302","stext":{"head":"§11302. General definition of homeless individual","paras":[[0,"(a) In general"],[0,"For purposes of this chapter, the terms \"homeless\", \"homeless individual\", and \"homeless person\" means— 1"],[1,"(1) an individual or family who lacks a fixed, regular, and adequate nighttime residence;"],[1,"(2) an individual or family with a primary nighttime residence that is a public or private place not designed for or ordinarily used as a regular sleeping accommodation for human beings, including a car, park, abandoned building, bus or train station, airport, or camping ground;"],[1,"(3) an individual or family living in a supervised publicly or privately operated shelter designated to provide temporary living arrangements (including hotels and motels paid for by Federal, State, or local government programs for low-income individuals or by charitable organizations, congregate shelters, and transitional housing);"],[1,"(4) an individual who resided in a shelter or place not meant for human habitation and who is exiting an institution where he or she temporarily resided;"],[1,"(5) an individual or family who—"],[2,"(A) will imminently lose their housing, including housing they own, rent, or live in without paying rent, are sharing with others, and rooms in hotels or motels not paid for by Federal, State, or local government programs for low-income individuals or by charitable organizations, as evidenced by—"],[3,"(i) a court order resulting from an eviction action that notifies the individual or family that they must leave within 14 days;"],[3,"(ii) the individual or family having a primary nighttime residence that is a room in a hotel or motel and where they lack the resources necessary to reside there for more than 14 days; or"],[3,"(iii) credible evidence indicating that the owner or renter of the housing will not allow the individual or family to stay for more than 14 days, and any oral statement from an individual or family seeking homeless assistance that is found to be credible shall be considered credible evidence for purposes of this clause;"],[2,"(B) has no subsequent residence identified; and"],[2,"(C) lacks the resources or support networks needed to obtain other permanent housing; and"],[1,"(6) unaccompanied youth and homeless families with children and youth defined as homeless under other Federal statutes who—"],[2,"(A) have experienced a long term period without living independently in permanent housing,"],[2,"(B) have experienced persistent instability as measured by frequent moves over such period, and"],[2,"(C) can be expected to continue in such status for an extended period of time because of chronic disabilities, chronic physical health or mental health conditions, substance addiction, histories of domestic violence or childhood abuse, the presence of a child or youth with a disability, or multiple barriers to employment."],[0,"(b) Domestic violence, dating violence, sexual assault, stalking, and other dangerous, traumatic, or life-threatening conditions relating to such violence"],[0,"Notwithstanding any other provision of this section, the Secretary shall consider to be homeless any individual or family who—"],[1,"(1) is experiencing trauma or a lack of safety related to, or fleeing or attempting to flee, domestic violence, dating violence, sexual assault, stalking, or other dangerous, traumatic, or life-threatening conditions related to the violence against the individual or a family member in the individual's or family's current housing situation, including where the health and safety of children are jeopardized;"],[1,"(2) has no other safe residence; and"],[1,"(3) lacks the resources to obtain other safe permanent housing."],[0,"(c) Income eligibility"],[0,"(1) In general"],[1,"A homeless individual shall be eligible for assistance under any program provided by this chapter, only if the individual complies with the income eligibility requirements otherwise applicable to such program."],[0,"(2) Exception"],[1,"Notwithstanding paragraph (1), a homeless individual shall be eligible for assistance under title I of the Workforce Innovation and Opportunity Act [29 U.S.C. 3111 et seq.]."],[0,"(d) Exclusion"],[0,"For purposes of this chapter, the term \"homeless\" or \"homeless individual\" does not include any individual imprisoned or otherwise detained pursuant to an Act of the Congress or a State law."],[0,"(e) Persons experiencing homelessness"],[0,"Any references in this chapter to homeless individuals (including homeless persons) or homeless groups (including homeless persons) shall be considered to include, and to refer to, individuals experiencing homelessness or groups experiencing homelessness, respectively."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/11302?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§11302. General definition of homeless individual","tname":"The Public Health and Welfare","by":{"3":"16"}},{"t":"case","label":"Boyd v. San Rafael","cite":"2023 WL 6960368","y":2023,"court":"N.D. Cal. Oct. 19","op":1,"by":{"4":"19"}},{"t":"case","label":"DeShaney v. Winnebago County Dept. of Social Servs.","cite":"489 U.S. 189","y":1989,"id":"1988/87-154","sc":1,"sum":"The Due Process Clause does not impose a special duty on the State to provide services to the public for protection against private actors if the State did not create those harms. \"The Clause is phrased as a limitation on the State's power to act, not as a guarantee of certain minimal levels of safety and security; while it forbids the State itself to deprive individuals of life, liberty, and property without due process of law, its language cannot fairly be read to impose an affirmative obligation on the State to ensure that those interests do not come to harm through other means.\".","sumSrc":"Oyez","by":{"4":"16"}},{"t":"case","label":"Halo Electronics, Inc. v. Pulse Electronics, Inc.","cite":"579 U.S. 93","y":2016,"id":"2015/14-1513","sc":1,"sum":"The Court determined that the rigid two-part test is not necessary for determining whether a patentee is eligible for enhanced damages under 35 U.S.C §284.","sumSrc":"Oyez","by":{"4":"13"}},{"t":"case","label":"Janus v. State, County, and Municipal Employees","cite":"585 U.S. 878","y":2018,"url":"https://supreme.justia.com/cases/federal/us/585/878/","sc":1,"by":{"4":"16"}},{"t":"case","label":"Jones v. Mississippi","cite":"593 U.S. 98","y":2021,"id":"2020/18-1259","sc":1,"op":2,"sum":"A discretionary sentencing system is both constitutionally necessary and constitutionally sufficient to sentence a defendant who committed a homicide when he or she was under 18 to life without parole; a separate factual finding of permanent incorrigibility is not required.","sumSrc":"Holding (supremecourt.gov)","by":{"4":"17"}},{"t":"case","label":"Knick v. Township of Scott","cite":"588 U.S. 180","y":2019,"id":"2018/17-647","sc":1,"sum":"A government violates the Takings Clause when it takes property without compensation, and a property owner may bring a Fifth Amendment claim under 42 U. S. C. §1983 at that time; the state-litigation requirement of Williamson County Regional Planning Comm’n v. Hamilton Bank of Johnson City, 473 U. S. 172, is overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"4":"9"}},{"t":"case","label":"People v. Forbes","cite":"19 How. Pr. 457","y":1860,"court":"N.Y.","url":"https://www.courtlistener.com/c/How.%20Pr./19/457/","by":{"4":"16"}},{"t":"case","label":"Quarles v. United States","cite":"139 S. Ct. 1872","y":2019,"id":"2018/17-778","sc":1,"ar":1,"sum":"Michigan’s third-degree home-invasion statute substantially corresponds to or is narrower than generic burglary for purposes of qualifying for enhanced sentencing under the Armed Career Criminal Act.","sumSrc":"Holding (supremecourt.gov)","by":{"4":"5"}},{"t":"case","label":"Taylor v. United States","cite":"495 U.S. 575","y":1990,"id":"1989/88-7194","sc":1,"sum":"An offense constitutes \"burglary\" under §924(e) if, regardless of its exact definition or label, it has the basic elements of a \"generic\" burglary-i. e., an unlawful or unprivileged entry into, or remaining in, a building or other structure, with intent to commit a crime-or if the charging paper and jury instructions actually required the jury to find all the elements of generic burglary in order to convict the …","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"12"}},{"t":"case","label":"United States v. Cooley","cite":"593 U.S. 345","y":2021,"id":"2020/19-1414","sc":1,"sum":"A tribal police officer has authority to detain temporarily and to search a non-Indian traveling on a public right-of-way running through a reservation for potential violations of state or federal law.","sumSrc":"Holding (supremecourt.gov)","by":{"4":"18"}},{"t":"usc","label":"18 U.S.C. § 2252","url":"https://www.law.cornell.edu/uscode/text/18/2252","by":{"4":"14"}},{"t":"usc","label":"21 U.S.C. § 844","url":"https://www.law.cornell.edu/uscode/text/21/844","by":{"4":"14"}},{"t":"reg","label":"70 Fed. Reg. 48,586","url":"https://www.govinfo.gov/link/fr/70/48586","by":{"4":"22"}}]};